#!/usr/bin/env bash
set -eo pipefail
export HOME=/root
cd /opt/mesocyclonic-viewer
rm -f scripts/model/build_dataset.py tests/test_model_dataset.py
mkdir -p scripts/model/config tests
echo '' | base64 -d > 'scripts/model/config/model_selection.yaml'
echo '' | base64 -d > 'scripts/model/indices.py'
echo '' | base64 -d > 'scripts/model/labels.py'
echo '' | base64 -d > 'scripts/model/features.py'
echo '' | base64 -d > 'scripts/model/kpis.py'
echo '' | base64 -d > 'scripts/model/models.py'
echo '' | base64 -d > 'scripts/model/cv.py'
echo '' | base64 -d > 'scripts/model/decide.py'
echo '' | base64 -d > 'scripts/model/train.py'
echo '' | base64 -d > 'scripts/model/score.py'
echo '' | base64 -d > 'scripts/model/plan_days.py'
echo '' | base64 -d > 'scripts/model/run_days.sh'
echo '' | base64 -d > 'tests/test_model_selection.py'
echo '' | base64 -d > 'pyproject.toml'
echo "archivos escritos:"; ls scripts/model/*.py scripts/model/config/*.yaml tests/test_model_selection.py | wc -l
echo TRANSFER_DONE
